#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "lwan-config.h"

static bool
dump(struct config *config, struct config_line *line, int indent_level)
{
    if (indent_level > 64)
        return false;

    while (config_read_line(config, line)) {
        switch (line->type) {
        case CONFIG_LINE_TYPE_LINE:
            break;

        case CONFIG_LINE_TYPE_SECTION_END:
            if (indent_level == 0)
                return false;

            return true;

        case CONFIG_LINE_TYPE_SECTION:
            if (!dump(config, line, indent_level + 1))
                return false;

            break;
        }
    }

    if (config_last_error(config)) {
        fprintf(stderr,
                "Error while reading configuration file (line %d): %s\n",
                config_cur_line(config), config_last_error(config));
        return false;
    }

    return true;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    static uint8_t static_data[32768];
    struct config *config;
    struct config_line line;
    int indent_level = 0;

    if (size > sizeof(static_data))
        size = sizeof(static_data);
    memcpy(static_data, data, size);

    config = config_open_for_fuzzing(static_data, size);
    if (!config)
        return 1;

    bool dumped = dump(config, &line, indent_level);

    config_close(config);

    return dumped ? 1 : 0;
}

---build---

mkdir -p $WORK/lwan
cd $WORK/lwan
cmake -GNinja   -DCMAKE_BUILD_TYPE=Debug        -DCMAKE_C_COMPILER="${CC}"      -DCMAKE_C_FLAGS="${CFLAGS}"     $SRC/lwan/
ninja -v liblwan.a
cp $SRC/lwan/fuzz/*.dict $OUT/
for fuzzer in $SRC/lwan/src/bin/fuzz/*_fuzzer.cc; do
        executable=$(basename $fuzzer .cc)
        corpus_base=$(basename $fuzzer _fuzzer.cc)
        zip -jr $OUT/${executable}_seed_corpus.zip $SRC/lwan/fuzz/corpus/corpus-${corpus_base}-*
        $CXX $CXXFLAGS -std=c++11               -Wl,-whole-archive $WORK/lwan/src/lib/liblwan.a -Wl,-no-whole-archive           -I$SRC/lwan/src/lib $fuzzer             $LIB_FUZZING_ENGINE -lpthread -lz               -o $OUT/$executable
done
